$(function(){$("#accordion").accordion({heightStyle:"content",active:!1,collapsible:!0,icons:{header:"ui-icon-circle-plus",activeHeader:"ui-icon-circle-minus"}});setTimeout(function(){$(".accordion-expand-all").trigger("click")},1e3)});$(".accordion-expand-all").click(function(){var n=$(".accordion-content-active");n.length>0?n.slideDown("slow"):toastr.warning(JSR.alert_no_level_class_selected)});$(".accordion-collapse-all").click(function(){$(".accordion-content-active").slideUp("slow")});